/// The SVG path subset the mark uses: M, Q, and Z, with absolute coordinates.
private func bezier(_ d: String) -> NSBezierPath {
    let path = NSBezierPath()
    let scanner = Scanner(string: d)
    scanner.charactersToBeSkipped = CharacterSet.whitespaces.union(CharacterSet(charactersIn: ","))
    var current = NSPoint.zero
    func point() -> NSPoint? {
        guard let x = scanner.scanDouble(), let y = scanner.scanDouble() else { return nil }
        return NSPoint(x: x, y: y)
    }
    while !scanner.isAtEnd {
        guard let command = scanner.scanCharacter() else { break }
        switch command {
        case "M":
            if let p = point() { path.move(to: p); current = p }
        case "Q":
            // NSBezierPath only draws cubic curves before macOS 14: raise the degree.
            if let c = point(), let p = point() {
                let c1 = NSPoint(x: current.x + 2 / 3 * (c.x - current.x), y: current.y + 2 / 3 * (c.y - current.y))
                let c2 = NSPoint(x: p.x + 2 / 3 * (c.x - p.x), y: p.y + 2 / 3 * (c.y - p.y))
                path.curve(to: p, controlPoint1: c1, controlPoint2: c2)
                current = p
            }
        case "Z", "z":
            path.close()
        default:
            break
        }
    }
    return path
}

/// The mark, fitted to a menu bar icon of `height` points.
func rabbitMark(height: CGFloat = 18) -> NSImage {
    let rabbit = bezier(rabbitPath)
    let eye = bezier(eyePath)
    let bounds = rabbit.bounds
    let side = max(bounds.width, bounds.height)
    let image = NSImage(size: NSSize(width: height, height: height), flipped: true) { rect in
        let inset: CGFloat = 1
        let scale = (rect.height - inset * 2) / side
        let transform = NSAffineTransform()
        transform.translateX(
            by: inset + (rect.width - inset * 2 - bounds.width * scale) / 2,
            yBy: inset + (rect.height - inset * 2 - bounds.height * scale) / 2
        )
        transform.scale(by: scale)
        transform.translateX(by: -bounds.minX, yBy: -bounds.minY)
        NSColor.black.setFill()
        for part in [rabbit, eye] {
            let copy = part.copy() as! NSBezierPath
            copy.transform(using: transform as AffineTransform)
            copy.fill()
        }
        return true
    }
    image.isTemplate = true
    image.accessibilityDescription = "White Rabbit Helper"
    return image
}
